sys_variable_value.value:
(function execute(inputs, outputs) {
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Workflow',
        'STAGE_TRANSITION',
        inputs.app_sys_id,
        inputs.req_sys_id,
        'New candidate application received',
        'Application acknowledged; stage moved to RECEIVED',
        null,
        '24-hour acknowledgement SLA met; Notification N-1 dispatched'
    );
})(inputs, outputs);

